	@Test
	void rewriteUpdatesInsertsDeletesAndAppendsAPredicatePartition() {
		List<Row> rows = List.of(
				new Row(id(1, 100), new long[] { id(1, 1_000) }, new long[] { 0 }),
				new Row(id(1, 102), new long[] { id(1, 1_002) }, new long[] { 0 }),
				new Row(id(1, 104), new long[] { id(1, 1_004) }, new long[] { 0 }));
		TrackingBudget budget = new TrackingBudget();
		try (ImmutablePagedQuadCsfIndex oldIndex = build(1, 0, 0, rows)) {
			Updates updates = new Updates(
					new int[] { 0, 0, 0, 4 },
					new long[] { id(1, 100), id(1, 101), id(1, 102), id(1, 77) },
					new boolean[] { false, false, true, false },
					new long[][] {
							{ id(1, 9_000), id(1, 9_001) },
							{ id(1, 1_001) },
							{},
							{ id(1, 7_700) }
					},
					new long[][] {
							{ 0, id(1, 9) },
							{ 0 },
							{},
							{ id(1, 7) }
					});

			ImmutablePagedQuadCsfIndex.RewriteResult rewrite = oldIndex.rewrite(2, updates, budget);
			try (ImmutablePagedQuadCsfIndex rewritten = rewrite.index()) {
				ImmutablePagedQuadCsfIndex.RowCursor cursor = new ImmutablePagedQuadCsfIndex.RowCursor();
				rewritten.resolve(rewritten.findLocalReference(0, 0, id(1, 100)), cursor);
				assertThat(cursor.edgeCount()).isEqualTo(2);
				assertThat(cursor.neighborAt(1)).isEqualTo(id(1, 9_001));
				assertThat(rewritten.findLocalReference(0, 0, id(1, 101))).isNotZero();
				assertThat(rewritten.findLocalReference(0, 0, id(1, 102))).isZero();
				assertThat(rewritten.findLocalReference(0, 0, id(1, 104))).isNotZero();
				assertThat(rewritten.findLocalReference(1, 0, id(1, 77))).isNotZero();

				oldIndex.resolve(oldIndex.findLocalReference(0, 0, id(1, 102)), cursor);
				assertThat(cursor.neighborAt(0)).isEqualTo(id(1, 1_002));
			}
			assertThat(budget.liveBytes).hasValue(0);
		}
	}

