	@Test
	void repeatedPageRewritesFlattenShardDependencyChains() {
		List<Row> rows = new ArrayList<>();
		for (int row = 0; row < 5_000; row++) {
			rows.add(new Row(id(1, 100L + row * 2L), new long[] { id(1, 10_000L + row) }, new long[] { 0 }));
		}
		TrackingBudget budget = new TrackingBudget();
		ImmutablePagedQuadCsfIndex current = build(1, 0, 0, rows);
		try {
			for (int rewrite = 0; rewrite < 40; rewrite++) {
				Updates updates = new Updates(new int[] { 0 }, new long[] { rows.get(0).row },
						new boolean[] { false }, new long[][] { { id(1, 1_000_000L + rewrite) } },
						new long[][] { { 0 } });
				ImmutablePagedQuadCsfIndex replacement = current.rewrite(1, updates, budget).index();
				current.close();
				current = replacement;
				assertThat(current.maxShardChainDepthForTest()).isLessThanOrEqualTo(32);
			}
		} finally {
			current.close();
		}
		assertThat(budget.liveBytes).hasValue(0);
	}

	private static void rewritesOnlyAffectedShardsAndRetainsOldSnapshotWithSmallShards() {
		List<Row> rows = new ArrayList<>();
		for (int row = 0; row < 12; row++) {
			long[] neighbours = new long[8_000];
			long[] contexts = new long[neighbours.length];
			long base = 10_000_000L + (long) row * 100_000L;
			for (int i = 0; i < neighbours.length; i++) {
				neighbours[i] = id(1, base + i * 3L);
			}
			rows.add(new Row(id(1, 100L + row * 2L), neighbours, contexts));
		}
		TrackingBudget budget = new TrackingBudget();
		try (ImmutablePagedQuadCsfIndex oldIndex = build(1, 0, 0, rows)) {
			assertThat(oldIndex.shardCount()).isGreaterThanOrEqualTo(2);
			Row changed = rows.get(10);
			long[] replacementNeighbours = { id(1, 777), id(1, 888) };
			long[] replacementContexts = { 0, id(1, 9) };
			Updates updates = new Updates(new int[] { 0 }, new long[] { changed.row }, new boolean[] { false },
					new long[][] { replacementNeighbours }, new long[][] { replacementContexts });

			ImmutablePagedQuadCsfIndex.RewriteResult rewrite = oldIndex.rewrite(1, updates, budget);
			try (ImmutablePagedQuadCsfIndex newIndex = rewrite.index()) {
				assertThat(rewrite.sharedShardCount()).isPositive();
				assertThat(rewrite.replacedShardCount()).isPositive();
				assertThat(rewrite.allocatedShardCount()).isPositive();

				ImmutablePagedQuadCsfIndex.RowCursor oldCursor = new ImmutablePagedQuadCsfIndex.RowCursor();
				oldIndex.resolve(oldIndex.findLocalReference(0, 0, changed.row), oldCursor);
				assertThat(oldCursor.edgeCount()).isEqualTo(changed.neighbours.length);

				ImmutablePagedQuadCsfIndex.RowCursor newCursor = new ImmutablePagedQuadCsfIndex.RowCursor();
				newIndex.resolve(newIndex.findLocalReference(0, 0, changed.row), newCursor);
				assertThat(newCursor.edgeCount()).isEqualTo(2);
				assertThat(newCursor.neighborAt(1)).isEqualTo(replacementNeighbours[1]);
				assertThat(newCursor.contextAt(1)).isEqualTo(replacementContexts[1]);

				Row unchanged = rows.get(rows.size() - 1);
				newIndex.resolve(newIndex.findLocalReference(0, 0, unchanged.row), newCursor);
				assertThat(newCursor.edgeCount()).isEqualTo(unchanged.neighbours.length);
				assertThat(budget.liveBytes).hasPositiveValue();
			}
			assertThat(budget.liveBytes).hasValue(0);
		}
	}

	private static ImmutablePagedQuadCsfIndex build(int predicates, long predicate, int plane, List<Row> rows) {
		ImmutablePagedQuadCsfIndex.BuildPlan plan;
		try (ImmutablePagedQuadCsfIndex.Builder sizing = ImmutablePagedQuadCsfIndex.sizingBuilder(predicates)) {
			feed(sizing, predicate, plane, rows);
			plan = sizing.finishPlan();
		}
		try (ImmutablePagedQuadCsfIndex.Builder materializing = ImmutablePagedQuadCsfIndex
				.materializingBuilder(plan)) {
			feed(materializing, predicate, plane, rows);
			return materializing.finishIndex();
		}
	}

	private static void feed(ImmutablePagedQuadCsfIndex.Builder builder, long predicate, int plane, List<Row> rows) {
		for (Row row : rows) {
			builder.beginRow(predicate, plane, row.row);
			for (int ordinal = 0; ordinal < row.neighbours.length; ordinal++) {
				builder.pair(row.neighbours[ordinal], row.contexts[ordinal]);
			}
			builder.endRow();
		}
	}

	private static long id(int type, long payload) {
		return payload << 7 | (long) type << 1;
	}

	private static long[] longs(List<Long> source) {
		long[] values = new long[source.size()];
		for (int i = 0; i < values.length; i++) {
			values[i] = source.get(i);
		}
		return values;
	}

	private static final class TrackingBudget implements ImmutablePagedQuadCsfIndex.MemoryBudget {
		private final AtomicLong liveBytes = new AtomicLong();

		@Override
		public ImmutablePagedQuadCsfIndex.MemoryReservation reserve(long nativeBytes, long modeledJavaBytes) {
			long total = Math.addExact(nativeBytes, modeledJavaBytes);
			liveBytes.addAndGet(total);
			AtomicBoolean closed = new AtomicBoolean();
			return () -> {
				if (closed.compareAndSet(false, true)) {
					liveBytes.addAndGet(-total);
				}
			};
		}
	}

	private static final class RefusingBudget implements ImmutablePagedQuadCsfIndex.MemoryBudget {
		private final int refusedCall;
		private final AtomicLong liveBytes = new AtomicLong();
		private int calls;

		private RefusingBudget(int refusedCall) {
			this.refusedCall = refusedCall;
		}

		@Override
		public ImmutablePagedQuadCsfIndex.MemoryReservation reserve(long nativeBytes, long modeledJavaBytes) {
			if (++calls == refusedCall) {
				throw new IllegalStateException("test reservation refused");
			}
			long total = Math.addExact(nativeBytes, modeledJavaBytes);
			liveBytes.addAndGet(total);
			AtomicBoolean closed = new AtomicBoolean();
			return () -> {
				if (closed.compareAndSet(false, true)) {
					liveBytes.addAndGet(-total);
				}
			};
		}
	}

	private static final class Updates implements ImmutablePagedQuadCsfIndex.RowUpdateSource {
		private final int[] partitions;
		private final long[] rows;
		private final boolean[] tombstones;
		private final long[][] neighbours;
		private final long[][] contexts;

		private Updates(int[] partitions, long[] rows, boolean[] tombstones, long[][] neighbours, long[][] contexts) {
			this.partitions = partitions;
			this.rows = rows;
			this.tombstones = tombstones;
			this.neighbours = neighbours;
			this.contexts = contexts;
		}

		@Override
		public int size() {
			return rows.length;
		}

		@Override
		public int partitionAt(int index) {
			return partitions[index];
		}

		@Override
		public long rowAt(int index) {
			return rows[index];
		}

		@Override
		public boolean tombstoneAt(int index) {
			return tombstones[index];
		}

		@Override
		public long pairCountAt(int index) {
			return tombstones[index] ? 0 : neighbours[index].length;
		}

		@Override
		public int copyPairsAt(int index, long fromOrdinal, int length, long[] neighbourTarget, int neighbourOffset,
				long[] contextTarget, int contextOffset) {
			int from = Math.toIntExact(fromOrdinal);
			int copied = Math.min(length, neighbours[index].length - from);
			System.arraycopy(neighbours[index], from, neighbourTarget, neighbourOffset, copied);
			System.arraycopy(contexts[index], from, contextTarget, contextOffset, copied);
			return copied;
		}
	}

	private record Row(long row, long[] neighbours, long[] contexts) {
		private Row {
			if (neighbours.length == 0 || neighbours.length != contexts.length) {
				throw new IllegalArgumentException("row columns must be non-empty and aligned");
			}
		}
	}
